//! The golden half of the save interop: this port's six scripted documents
//! against the records `tools/oracle`'s `save-interop` wrote into
//! `test/golden/save-interop.jsonl`. Nothing in this file writes that corpus —
//! it is generated by the reference.
//!
//! Every case rebuilds its scenario through this port's own manual
//! transactions (`save_interop_scenarios.zig`), independently of the reference,
//! and then checks: the record's provenance and scenario, the head **set**,
//! every change **by hash identity** with its `seq`, `start_op` and whole framed
//! chunk, the reference's save **loading** through this port's reader with
//! [`Document.debugCmp`] and hydration equality together, and this port's own
//! **default** `save()` normalizing to the same bytes as the reference's.
//!
//! **Normalization is a claim about which bytes are allowed to differ.** DEFLATE
//! is not reproducible across implementations — the one thing a save is *not*
//! required to reproduce — so the body comparison is over inflated column
//! content instead. The two regressions below are what make that a claim rather
//! than an assertion. One writes the `list` document's block back out twice,
//! once with no compression at all and once compressed with a single flipped
//! byte inside a column longer than the deflate threshold: the uncompressed
//! form must report no deflated descriptor at all (so the count is read off the
//! wire and not re-derived from a threshold), both forms must normalize to the
//! same body, and the compressed one must still differ from the original in
//! exactly that one byte. The other requires a save with bytes after its
//! document chunk to be refused instead of normalized away.
//!
//! Everything is reached through the named `zautomerge` import, so nothing here
//! can see a private: the root is the surface a consumer gets, and the surface
//! the interop claim is about.

const std = @import("std");

/// The module under test, imported by the name a consumer imports it by.
const am = @import("zautomerge");

/// The scripts, and the comparisons both directions of the interop make.
const scenarios = @import("save_interop_scenarios.zig");

const testing = std.testing;

/// **The leak arbiter for every case below.** One allocator, named once, and
/// every owned value comes out of it: each document, each save, each parse.
const gpa = testing.allocator;

/// The borrowed capability every document constructor is handed. **Explicit,
/// because `Document` keeps it** — the op set draws actors through this value
/// for as long as the document lives.
const io = testing.io;

/// Where the generated corpus lives, relative to the process working
/// directory.
///
/// **Probed rather than assumed**, the way `sync/v1.zig` and
/// `hexane/codec_golden.zig` probe: a unit test binary inherits the directory it
/// was started in, which is the build root under `zig build test` and this
/// file's own directory under a direct `zig test`.
const golden_paths = [_][]const u8{
    "test/golden/save-interop.jsonl",
    "../test/golden/save-interop.jsonl",
    "../../test/golden/save-interop.jsonl",
};

/// The name a diagnostic uses when none of the paths above was there.
const golden_name = "test/golden/save-interop.jsonl";

/// Ceiling on the corpus, four times what six records of this shape need: each
/// carries a whole document in hex, and the `list` scenario's save is the
/// largest.
const max_golden_bytes = 1 << 23;

/// The generated corpus, read into `arena`.
///
/// A missing file is **not** a skip. The corpus is the reference's and is
/// generated by `zig build conformance -Dconformance-record -Dconformance-vector=save-interop`; a test that quietly
/// passed without it would be a test that checked nothing.
fn readGolden(arena: std.mem.Allocator) ![]const u8 {
    for (golden_paths) |path| {
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, path, arena, .limited(max_golden_bytes)) catch |e| switch (e) {
            error.FileNotFound, error.NotDir => continue,
            else => return e,
        };
        return bytes;
    }
    std.debug.print("save-interop: {s} not found; tried", .{golden_name});
    for (golden_paths) |path| std.debug.print(" {s}", .{path});
    std.debug.print(
        "\n  generate it with `zig build conformance -Dconformance-record -Dconformance-vector=save-interop`\n",
        .{},
    );
    return error.GoldenVectorsNotFound;
}

/// Builds `id` again and checks it against the reference's record for it.
///
/// The corpus is read and its cardinality and uniqueness checked on the way,
/// which is what stops a golden file missing a scenario from letting five of six
/// cases report success.
fn check(id: scenarios.Id) !void {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const text = try readGolden(arena);
    const records = try scenarios.parseRecords(arena, text);
    const record = try scenarios.requireEveryScenario(records, id, golden_name);
    try scenarios.checkCase(gpa, io, id, record, scenarios.golden_kind);
}

// ── The six cases ────────────────────────────────────────────────────────────

test "map: every scalar type, a counter, a delete and a nested map agree with the reference" {
    try check(.map);
}

test "list: two hundred elements and a spliced second commit agree with the reference" {
    try check(.list);
}

test "text: three transactions over two text objects agree with the reference" {
    try check(.text);
}

test "marks: every expansion, plus an unmark in the same transaction, agree with the reference" {
    try check(.marks);
}

test "conflicts: the peer's change applied without a merge agrees with the reference" {
    try check(.conflicts);
}

test "merge: both merges, and no change of its own, agree with the reference" {
    try check(.merge);
}

// ── What normalization does and does not normalize ───────────────────────────

test "the deflate count is read off the wire, and normalization removes compression and nothing else" {
    var doc = try scenarios.build(gpa, io, .list);
    defer doc.deinit();
    const saved = try doc.save(gpa);
    defer gpa.free(saved);

    var intact = try scenarios.normalize(gpa, saved);
    defer intact.deinit(gpa);
    // The subject of this case: a save that really did put a DEFLATE stream on
    // the wire, counted from the body as stored and confirmed by the parse
    // having had to rebuild it.
    try testing.expect(intact.deflated_columns > 0);
    try testing.expect(intact.inflated);

    const framed = try am.storage.chunk.parseChunk(saved);
    var parsed = try am.storage.document_chunk.parseFramedChunk(framed, gpa);
    defer parsed.deinit(gpa);

    // **The parse rebuilt the body**, so every column range indexes `inflated`
    // and that buffer is what the writer reproduces. A save with no deflated
    // column would index the caller's own bytes instead and there would be
    // nothing here to alter — which is why this case is the `list` corpus.
    const rebuilt = parsed.inflated orelse return error.NoDeflatedColumn;

    // **The widest operation column**, which is at or above the size the writer
    // deflates at. Checked rather than assumed: `columns[0]` on an empty set is
    // a trap in a `ReleaseFast` build, and a case whose subject has vanished
    // should say so rather than read out of bounds.
    const ops = parsed.block.ops;
    if (ops.columns.len == 0) return error.NoOpColumns;
    var widest = ops.columns[0];
    for (ops.columns[1..]) |column| {
        if (column.len() > widest.len()) widest = column;
    }
    try testing.expect(widest.len() >= am.storage.document_chunk.deflate_min_size);

    // **The same block written with no compression at all.** Its body holds a
    // column longer than the deflate threshold, so a count that re-derived the
    // threshold from the inflated body would call it deflated; a count that
    // reads the descriptors has nothing to read, and the parse borrows the
    // caller's bytes instead of rebuilding them. The two agree about the
    // content, which is the whole claim: normalization removes the compression
    // and not one byte of the document.
    const plain_chunk = try am.storage.document_chunk.encode(gpa, parsed.block, .none);
    defer gpa.free(plain_chunk);
    var plain = try scenarios.normalize(gpa, plain_chunk);
    defer plain.deinit(gpa);
    try testing.expectEqual(@as(usize, 0), plain.deflated_columns);
    try testing.expect(!plain.inflated);
    try testing.expectEqualSlices(u8, intact.body, plain.body);

    // **One byte, inside that column.** `RawColumn.bytes` is the parser's own
    // view of the column, and it indexes the rebuilt body, so the offset is
    // taken from that view rather than from `range.start`, which is relative to
    // the op data block and not to the body.
    const column_bytes = try widest.bytes(ops.data);
    const at = @intFromPtr(column_bytes.ptr) - @intFromPtr(rebuilt.ptr);
    if (at >= rebuilt.len) return error.NoColumnBytes;
    rebuilt[at] ^= 0x01;

    // **A real compressed document chunk, through the writer**, with the same
    // policy `save()` uses. The alteration therefore travels through a DEFLATE
    // stream on the wire, and both sides of the comparison below are framed
    // saves parsed by `normalize` rather than bodies encoded from a block.
    const altered_chunk = try am.storage.document_chunk.encode(
        gpa,
        parsed.block,
        .{ .threshold = am.storage.document_chunk.deflate_min_size },
    );
    defer gpa.free(altered_chunk);
    var altered = try scenarios.normalize(gpa, altered_chunk);
    defer altered.deinit(gpa);
    try testing.expect(altered.inflated);

    // Same length, and **exactly one byte different**: one byte of one column,
    // with every actor, head, descriptor, ordering, encoding and other column
    // byte untouched. A normalization that dropped or zeroed a column to make
    // two documents look alike, or one that let a deflated stream through
    // without inflating it, fails here.
    try testing.expectEqual(intact.body.len, altered.body.len);
    var differing: usize = 0;
    for (intact.body, altered.body) |mine, theirs| {
        if (mine != theirs) differing += 1;
    }
    try testing.expectEqual(@as(usize, 1), differing);
}

test "a save with bytes after its document chunk is refused rather than normalized" {
    // **The shape a save with queued changes has**, and the one an orphan change
    // chunk produces: the document chunk followed by more bytes. `parseChunk`
    // refuses the trailing bytes, so nothing downstream ever sees a
    // "normalized" body that quietly dropped the second chunk.
    var doc = try scenarios.build(gpa, io, .list);
    defer doc.deinit();
    const saved = try doc.save(gpa);
    defer gpa.free(saved);

    const magic = am.storage.chunk.magic;
    const trailing = try gpa.alloc(u8, saved.len + magic.len);
    defer gpa.free(trailing);
    @memcpy(trailing[0..saved.len], saved);
    @memcpy(trailing[saved.len..], &magic);

    try testing.expectError(error.TrailingBytes, scenarios.normalize(gpa, trailing));
}
